from itertools import product

# Ground facts and ordinary background knowledge used to interpret the state.
facts = {
    "camel_movie_after_maradona_death": 2015 > 2020,
    "camel_has_seat": False,  # Not established; a knapsack belongs to the llama.
    "camel_works_in_agriculture": True,  # Grain elevator operator.
    "pelikan_and_elk_names_share_initial": "Luna"[0] == "Lucy"[0],
    "pelikan_movie_after_facebook_founding": False,  # No pelikan movie given.
    "llama_took_bike_from_store": False,  # Parking a bike does not establish this.
    "llama_in_south_america": True,  # Argentina is in South America.
    "llama_works_in_computing": False,
    "llama_has_musical_instrument": False,
}

# Literals: S = camel surrenders, C = pelikan captures, L = llama leaves,
# W = gadwall wants to see the swan. "~" denotes explicit negation.
rules = {
    1:  (("S",), "~W"),
    2:  (("camel_movie_after_maradona_death",), "~S"),
    3:  (("pelikan_and_elk_names_share_initial",), "~C"),
    4:  (("camel_has_seat",), "~S"),
    5:  (("pelikan_movie_after_facebook_founding",), "C"),
    6:  (("llama_took_bike_from_store",), "~L"),
    7:  (("~L", "~C"), "W"),
    8:  (("camel_works_in_agriculture",), "S"),
    9:  (("llama_works_in_computing",), "L"),
    10: (("llama_in_south_america",), "~L"),
    11: (("llama_has_musical_instrument",), "L"),
}
preferred = {
    (11, 10), (11, 6), (2, 8), (4, 8),
    (5, 3), (7, 1), (9, 10), (9, 6),
}

def opposite(literal):
    return literal[1:] if literal.startswith("~") else "~" + literal

literals = sorted({head for _, head in rules.values()})
true_facts = {name for name, value in facts.items() if value}

def consequences(model):
    available = true_facts | model
    applicable = {
        number for number, (body, _) in rules.items()
        if all(antecedent in available for antecedent in body)
    }
    accepted = set()
    for number in applicable:
        head = rules[number][1]
        attackers = {
            other for other in applicable
            if rules[other][1] == opposite(head)
        }
        # Every applicable contrary rule must be overridden by an applicable
        # supporting rule. Unsupported antecedents never trigger a rule.
        if all(
            any(
                rules[supporter][1] == head
                and (supporter, attacker) in preferred
                for supporter in applicable
            )
            for attacker in attackers
        ):
            accepted.add(head)
    return accepted

# Exhaustively find all supported, preference-respecting fixed points.
models = []
for bits in product((False, True), repeat=len(literals)):
    model = {literal for literal, present in zip(literals, bits) if present}
    if any(opposite(literal) in model for literal in model):
        continue
    if consequences(model) == model:
        models.append(model)

print("Supported models:", len(models))
for model in models:
    print("Conclusions:", ", ".join(sorted(model)))

if not models:
    print("UNSUPPORTED")
    print("CHECK UNKNOWN")
else:
    if all("W" in model and "~W" not in model for model in models):
        expected = "proved"
    elif all("~W" in model and "W" not in model for model in models):
        expected = "disproved"
    else:
        expected = "unknown"
    print("Expected result:", expected)
    print("Submitted claim: the gadwall wants to see the swan")
    print("CHECK PASS" if expected == "proved" else "CHECK FAIL")
